//! Repository for CurrencyExchange entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below hold the FX engine's rate SQL (4-layer rule: services orchestrate, repos hold SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<CurrencyExchange, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use chrono::NaiveDate;
use rust_decimal::Decimal;
use sqlx::{PgConnection, PgPool, Row};
use uuid::Uuid;

use crate::domain::entity::CurrencyExchange;

/// Table name for CurrencyExchange entities
pub const TABLE_NAME: &str = "corporate.currency_exchanges";

/// Repository for CurrencyExchange entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct CurrencyExchangeRepository(
    backbone_orm::GenericCrudRepository<CurrencyExchange, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for CurrencyExchangeRepository {
    type Target = backbone_orm::GenericCrudRepository<CurrencyExchange, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl CurrencyExchangeRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// Bind `company` onto `conn` transaction-local via `set_config('app.company_id', ..., true)` — the
/// `true` scopes the setting to the surrounding transaction, so it is discarded on commit/rollback and
/// cannot leak onto a pooled connection reused by the next request.
///
/// This is corporate's local equivalent of the ORM's `company_scope::bind_company_on` (ADR-0008
/// follow-up: switch to the framework helper once this crate's `backbone-orm` pin propagates a release
/// that exports `company_scope`). It lives in the persistence layer — not the service — so the service
/// holds no SQL (4-layer rule).
pub async fn bind_company_tx(conn: &mut PgConnection, company: Uuid) -> Result<(), sqlx::Error> {
    sqlx::query("SELECT set_config('app.company_id', $1, true)")
        .bind(company.to_string())
        .execute(conn)
        .await?;
    Ok(())
}

/// The exact row an FX-rate insert writes.
pub struct NewCurrencyExchangeRow {
    pub id: Uuid,
    pub company_id: Option<Uuid>,
    pub from_currency: String,
    pub to_currency: String,
    pub rate: Decimal,
    pub effective_from: NaiveDate,
    pub effective_to: Option<NaiveDate>,
}

/// FX rate SQL. Lives here (not in the service) per the module's 4-layer rule.
impl CurrencyExchangeRepository {
    /// Overlap check within one company scope: two windows [a1,b1] and [a2,b2] overlap iff
    /// a1 <= b2 AND a2 <= b1, a null end treated as +infinity. Runs on the caller's scoped tx.
    pub async fn find_overlap_tx(
        &self,
        conn: &mut PgConnection,
        from: &str,
        to: &str,
        company_id: Option<Uuid>,
        effective_from: NaiveDate,
        effective_to: Option<NaiveDate>,
    ) -> Result<Option<Uuid>, sqlx::Error> {
        sqlx::query_scalar(
            r#"SELECT id FROM corporate.currency_exchanges
               WHERE from_currency=$1 AND to_currency=$2
                 AND company_id IS NOT DISTINCT FROM $3
                 AND (metadata->>'deleted_at') IS NULL
                 AND effective_from <= COALESCE($5, DATE '9999-12-31')
                 AND $4 <= COALESCE(effective_to, DATE '9999-12-31')
               LIMIT 1"#,
        )
        .bind(from).bind(to).bind(company_id).bind(effective_from).bind(effective_to)
        .fetch_optional(conn).await
    }

    /// Insert a rate row on the caller's scoped tx.
    pub async fn insert_rate_tx(
        &self,
        conn: &mut PgConnection,
        r: &NewCurrencyExchangeRow,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"INSERT INTO corporate.currency_exchanges
                 (id, company_id, from_currency, to_currency, rate, effective_from, effective_to)
               VALUES ($1,$2,$3,$4,$5,$6,$7)"#,
        )
        .bind(r.id).bind(r.company_id).bind(&r.from_currency).bind(&r.to_currency).bind(r.rate)
        .bind(r.effective_from).bind(r.effective_to)
        .execute(conn).await?;
        Ok(())
    }

    /// The effective rate (+ its row id) for a directed pair on a date, or None. Company scope wins
    /// over global; among a scope the most recent window wins (overlap is prevented on write). Runs
    /// on the caller's tx, which already carries `app.company_id` when scoped; the SQL predicate
    /// keeps the company-wins-over-global ordering explicit as defense-in-depth.
    pub async fn find_effective_rate_tx(
        &self,
        conn: &mut PgConnection,
        from: &str,
        to: &str,
        on_date: NaiveDate,
    ) -> Result<Option<(Decimal, Uuid)>, sqlx::Error> {
        let row = sqlx::query(
            r#"SELECT id, rate FROM corporate.currency_exchanges
               WHERE from_currency=$1 AND to_currency=$2
                 AND (company_id IS NOT DISTINCT FROM NULLIF(current_setting('app.company_id', true), '')::uuid
                      OR company_id IS NULL)
                 AND (metadata->>'deleted_at') IS NULL
                 AND effective_from <= $3
                 AND (effective_to IS NULL OR effective_to >= $3)
               ORDER BY (company_id IS NOT NULL) DESC, effective_from DESC
               LIMIT 1"#,
        )
        .bind(from).bind(to).bind(on_date)
        .fetch_optional(conn).await?;
        Ok(row.map(|r| (r.get::<Decimal, _>("rate"), r.get::<Uuid, _>("id"))))
    }
}

backbone_core::impl_crud_repository!(CurrencyExchangeRepository, CurrencyExchange, soft_delete);
